import React from 'react';
import { Link } from 'react-router-dom';
import bunnycloud from './assets/bunnycloud.png';  
import amulet from './assets/Amulet.jpeg';
import anthropology from './assets/anthropology.png';
import articuno from './assets/articuno.png';
import background from './assets/background.jpg';
import beanbean from './assets/beanbean.png';
import butterfly from './assets/butterfly.png';
import logo from './assets/logo.png';
import moltres from './assets/moltres.png';
import onion from './assets/onion.png';
import paintingAustralia from './assets/paintingAustralopithicus.jpeg';
import pockethome from './assets/pockethome.png';
import zapdo from './assets/zapdo.png';

const items = [
  { id: 1, image: bunnycloud, title: 'Bunny Cloud', description: 'A fluffy bunny cloud.' },
  { id: 2, image: amulet, title: 'Amulet', description: 'A magical amulet image.' },
  { id: 3, image: anthropology, title: 'Anthropology', description: 'Anthropology image.' },
  { id: 4, image: articuno, title: 'Articuno', description: 'Legendary bird Articuno.' },
  { id: 5, image: background, title: 'Background', description: 'Beautiful background image.' },
  { id: 6, image: beanbean, title: 'Bean Bean', description: 'A cute bean character.' },
  { id: 7, image: butterfly, title: 'Butterfly', description: 'Colorful butterfly image.' },
  { id: 8, image: logo, title: 'Logo', description: 'Artistic logo design.' },
  { id: 9, image: moltres, title: 'Moltres', description: 'Legendary bird Moltres.' },
  { id: 10, image: onion, title: 'Onion', description: 'Onion illustration.' },
  { id: 11, image: paintingAustralia, title: 'Australia Painting', description: 'A painting of Australia.' },
  { id: 12, image: pockethome, title: 'Pocket Home', description: 'Pocket home design.' },
  { id: 13, image: zapdo, title: 'Zapdos', description: 'Legendary bird Zapdos.' },
  // Add more images as necessary
];

const Gallery = () => {
  return (
    <div className="gallery-grid">
      {items.map((item) => (
        <div className="gallery-item" key={item.id}>
          <Link to={`/art/${item.id}`}>
            <img src={item.image} alt={item.title} className="gallery-image" />
            <h3>{item.title}</h3>
          </Link>
        </div>
      ))}
    </div>
  );
};

export default Gallery;
